impl Solution {
    pub fn minimum_deletions(nums: Vec<i32>) -> i32 {
        let n = nums.len();
        if n == 1 {
            return 1;
        }

        let min_val = *nums.iter().min().unwrap();
        let max_val = *nums.iter().max().unwrap();
        let min_idx = nums.iter().position(|&x| x == min_val).unwrap();
        let max_idx = nums.iter().position(|&x| x == max_val).unwrap();

        let left = std::cmp::min(min_idx, max_idx) + 1;
        let right = n - std::cmp::max(min_idx, max_idx);
        let both = min_idx + 1 + n - max_idx;

        std::cmp::min(std::cmp::min(left, right), both) as i32
    }
}
